<?php/** * Created by PhpStorm. * User: zy * Date: 2020/3/4 * Time: 15:31 */namespace App\Http\Controllers\V1\CategoryTemplate;use App\Common\Constant;use App\Exceptions\Error;use App\Http\Controllers\V1\BaseController;use CrsSdk\MicroGoodsV1\Goods;use CrsSdk\Shop\CategoryTemplate;use Illuminate\Http\Request;use Illuminate\Support\Facades\Log;class CategoryGoodsListController extends BaseController{    /**     * @param Request $request     * @return array     * @throws \Illuminate\Validation\ValidationException     */    public function index(Request $request)    {        $input                  = $this->getParams($request);        $input['enterprise_id'] = $this->enterpriseId;        $input['page']          = $request->input('page', 1);        $search                 = $request->get('search_name', '');        $searchType             = $request->get('search_type');        $size = $request->input('size', 10);        // 如果是条件搜索，则要获取更多的数据，来匹配条件，还要保持当前页数据量充足        $input['size']          = $size;        $data['list'] = [];        try {            $list = (new CategoryTemplate())->categoryGoodsList($input);            // 获取商品信息            if (!empty($list['list'])) {                $cond['source_ids']    = [$this->enterpriseId];                $cond['spu_ids']       = array_unique(array_column($list['list'], 'spu_id'));                $cond['is_selection']  = Constant::NOT_SPU_SELECTION;                $cond['page']          = 1;                $cond['size']          = 1000;                $cond['enterprise_id'] = $this->enterpriseId;                $cond['search'] = $search;                $cond['search_type'] = $searchType;                $spuData = (new Goods())->spuList($cond);                $data['size'] = $size;                $data['page'] = $input['page'];                if (!empty($search)) {                    $data['total'] = $spuData['total'];                } else {                    $data['total'] = $list['total'];                }                $spuKeyList = array_combine_by_key($spuData['list'], 'id');                $i = 0;                foreach ($list['list'] as $k => $v) {                    // 条件搜索，优先展示条件                    if (!empty($search) && empty($spuKeyList[$v['spu_id']])) {                        unset($list['list'][$k]);                        continue;                    }                    $list['list'][$k]['name']   = isset($spuKeyList[$v['spu_id']]['spu_name']) ? $spuKeyList[$v['spu_id']]['spu_name'] : '';                    $list['list'][$k]['pic']    = isset($spuKeyList[$v['spu_id']]['url']) ? $spuKeyList[$v['spu_id']]['url'] : '';                    $list['list'][$k]['spu_sn'] = isset($spuKeyList[$v['spu_id']]['spu_sn']) ? $spuKeyList[$v['spu_id']]['spu_sn'] : '';                    $data['list'][] = $list['list'][$k];                    $i++;                    // 填充完数据退出数据填充                    if ($i == $size) {                        break;                    }                }            }        } catch (Error $error) {            Log::info('分类关联商品列表失败', $error->data);            notice(100000, [$error->getMessage()], $error->data);        } catch (\Exception $e) {            Log::info('分类关联商品列表失败' . $e->getMessage(), $input);            notice(100000, [$e->getMessage()]);        }        return success($data);    }    /**     * 验证数据     * @param $request     * @return array     * @throws \Illuminate\Validation\ValidationException     */    protected function getParams($request)    {        // 验证参数        $rule = [            'cate_id' => 'required|integer',        ];        $messages = [            'cate_id.*' => '分类不存在',        ];        return $this->validate($request, $rule, $messages);    }}